fn check_local_profile(pdg: &PdgDocument, cfg: &CfgDocument) -> Result<bool, Vec<String>> {
    use rstyle_pdg::extraction_profile::LOCAL_ID;
    if pdg.profile.id != LOCAL_ID
        && pdg.profile.id != "rstyle.rust.hir-helpers"
        && pdg.profile.id != rstyle_pdg::extraction_profile::DATA_ID
    {
        return Ok(false);
    }
    if cfg.profile.name != pdg.profile.id || cfg.profile.version != pdg.profile.version {
        return Err(vec!["Paired extraction profiles disagree".into()]);
    }
    Ok(true)
}

pub fn token(self) -> &'static str {
        match self {
            Self::Validation => "validation",
            Self::Projection => "projection",
            Self::Nonempty => "nonempty",
            Self::SizeRatio => "size_ratio",
            Self::Numerical => "numerical",
            Self::Strings => "strings",
            Self::WlFinal => "wl_final",
        }
    }

pub(super) fn certify(
    facts: &dyn EvidenceFacts,
) -> Result<Option<(Summary, producer::Pair)>, String> {
    // A raw match shape cannot substitute for the complete source receipt.
    if activation::verify(facts).is_err() {
        return Ok(None);
    }
    let pair = producer::produce(facts).map_err(|errors| errors.join("; "))?;
    let summary = crate::diagnostics::Stage::new("helper.digit-product-summary", &facts.name, None)
        .observe(|| derive(facts, &pair))?;

    Ok(Some((summary, pair)))
}

