pub(super) fn certify(
    facts: &dyn EvidenceFacts,
) -> Result<Option<(Summary, producer::Pair)>, String> {
    // A raw match shape cannot substitute for the complete source receipt.
    if activation::verify(facts).is_err() {
        return Ok(None);
    }
    let pair = producer::produce(facts).map_err(|errors| errors.join("; "))?;
    let summary = crate::diagnostics::Stage::new("helper.digit-product-summary", &facts.name, None)
        .observe(|| derive(facts, &pair))?;

    Ok(Some((summary, pair)))
}

fn derive(facts: &dyn EvidenceFacts, pair: &producer::Pair) -> Result<Summary, String> {
    if !candidate(facts)
        || !crate::extraction_profile::policy_supports(&pair.pdg.profile, CAPABILITY)
        || pair.cfg.extraction_evidence.status != ExtractionStatus::Complete
    {
        return Err("Digit helper requires its complete registered parser contract".into());
    }
    let checked = activation::verify(facts)?;
    crate::scalar_product_instances::origins::documents::verify(pair.as_view(), &checked, facts)?;
    let replay = graph::verify(pair.as_view(), checked.prefix())?;
    let reads = reads(pair, &checked, &replay)?;
    let suffix = Output {
        selectors: vec![0, 0],
        ty: TypeToken::from_tree(&checked.instance().fields[0].ty),
        origins: vec![Origin {
            parameter: 0,
            path: vec![
                Projection::SharedReferent,
                Projection::PrefixSuffix {
                    start: checked.prefix().consumed(),
                },
            ],
        }],
    };

    Ok(Summary {
        identity: SUMMARY.into(),
        argument_types: argument_types(facts)?,
        result_type: result_type(facts)?,
        mutates_arguments: false,
        memory_effects: true,
        may_panic: false,
        always_returns: true,
        argument_evaluation: "source-order-once/1".into(),
        result_dependence: DEPENDENCE.into(),
        bounded_loop: None,
        reference_outputs: None,
        component_outputs: Some(vec![suffix]),
        memory_reads: Some(reads),
        tagged_output: None,
    })
}

pub(crate) fn candidate(facts: &dyn EvidenceFacts) -> bool {
    crate::extraction_profile::facts_support(facts, CAPABILITY)
        && activation::candidate(facts)
        && facts.body.kind == "expr_block"
        && matches!(facts.body.children.as_slice(), [matched] if matched.kind == "expr_match")
}

fn reads(
    pair: &producer::Pair,
    checked: &activation::Checked<'_>,
    replay: &graph::Replay<'_>,
) -> Result<Vec<Read>, String> {
    let mut reads = Vec::new();
    for ((selector, region), digit) in replay.selector_reads.iter().zip(checked.prefix().digits()) {
        let origin = region.checked_origin(checked.prefix())?;
        let body = crate::data_documents::value_operation(pair.as_view(), digit.read())?;
        for operation in [*selector, body] {
            reads.push(read(operation, &origin, pair)?);
        }
    }
    let observed = pair
        .pdg
        .nodes
        .iter()
        .flat_map(|node| &node.attributes.reads)
        .filter(|access| access.location_id.is_some())
        .count();
    if observed != reads.len() || reads.len() != usize::from(checked.prefix().consumed()) * 2 {
        return Err(
            "Digit helper omits or duplicates conditional physical read occurrences".into(),
        );
    }

    Ok(reads)
}

fn read(
    operation: &crate::PdgNode,
    origin: &Origin,
    pair: &producer::Pair,
) -> Result<Read, String> {
    let [access] = operation.attributes.reads.as_slice() else {
        return Err("Digit helper requires one physical access per source read".into());
    };
    let location = pair
        .pdg
        .memory_locations
        .iter()
        .find(|location| Some(&location.id) == access.location_id.as_ref())
        .ok_or("Digit helper read lacks its exact physical location")?;
    let evidence = &location.extensions[crate::data_documents::LOCATION_KEY];
    let path = serde_json::to_value(&origin.path).map_err(|error| error.to_string())?;
    let value = TypeToken::Scalar("u8".into());
    if location.abstraction != "rstyle.formal-prefix-element/1"
        || evidence["parameter"] != origin.parameter
        || evidence["path"] != path
        || evidence["type"] != serde_json::to_value(&value).map_err(|error| error.to_string())?
    {
        return Err("Digit helper physical read changes its saved prefix element".into());
    }

    Ok(Read {
        operation: operation.id.clone(),
        access: 0,
        parameter: origin.parameter,
        path: origin.path.clone(),
        value,
    })
}

fn unpack(&mut self, index: usize, depth: usize) -> Result<Value, String> {
        check_depth(depth)?;
        let fields = self
            .nodes
            .get(index)
            .and_then(Value::as_array)
            .ok_or("Missing or malformed helper transport node")?
            .clone();
        self.used.insert(index);
        self.charge(1)?;

        self.value(&fields, index, depth)
    }

fn value(&mut self, fields: &[Value], index: usize, depth: usize) -> Result<Value, String> {
        match fields.first().and_then(Value::as_str) {
            Some("literal")
                if fields.len() == 2 && !fields[1].is_object() && !fields[1].is_array() =>
            {
                self.charge(fields[1].as_str().map_or(1, str::len))?;
                Ok(fields[1].clone())
            }
            Some("json" | "quoted") => self.encoded_string(fields, index, depth),
            Some("text" | "array" | "object") if fields.len() == 2 => {
                self.collection(fields, index, depth)
            }
            _ => Err("Unsupported or malformed helper transport tag".into()),
        }
    }

fn collection(
        &mut self,
        fields: &[Value],
        index: usize,
        depth: usize,
    ) -> Result<Value, String> {
        match fields[0].as_str() {
            Some("array") => {
                let ids = fields[1]
                    .as_array()
                    .ok_or("Malformed helper transport array")?;
                ids.iter()
                    .map(|id| self.child(id, index, depth))
                    .collect::<Result<_, _>>()
                    .map(Value::Array)
            }
            Some("text") => self.text(&fields[1], index, depth),
            Some("object") => self.object(&fields[1], index, depth),
            _ => Err("Malformed helper transport collection tag".into()),
        }
    }

fn encoded_string(
        &mut self,
        fields: &[Value],
        index: usize,
        depth: usize,
    ) -> Result<Value, String> {
        let text = match fields[0].as_str() {
            Some("json") if fields.len() == 3 => {
                let format = fields[1]
                    .as_str()
                    .ok_or("Malformed helper transport JSON format")?;
                let value = self.child(&fields[2], index, depth)?;
                render(&value, format)?
            }
            Some("quoted") if fields.len() == 2 => {
                let text = super::transport_lexical::string(self.child(&fields[1], index, depth)?)?;
                render(&Value::String(text), "compact")?
            }
            _ => return Err("Malformed helper transport string tag".into()),
        };
        self.charge(text.len())?;

        Ok(Value::String(text))
    }

fn child(&mut self, value: &Value, parent: usize, depth: usize) -> Result<Value, String> {
        let index = value
            .as_u64()
            .and_then(|index| usize::try_from(index).ok())
            .filter(|index| *index < parent)
            .ok_or("Cyclic, forward or invalid helper transport index")?;
        self.unpack(index, depth + 1)
    }

fn object(
        &mut self,
        object: serde_json::Map<String, Value>,
        depth: usize,
    ) -> Result<Value, String> {
        self.sequence("object", object, |table, (key, value)| {
            table
                .pack(value, depth + 1)
                .map(|id| serde_json::json!([key, id]))
        })
    }

fn text(&mut self, value: &Value, index: usize, depth: usize) -> Result<Value, String> {
        let ids = value
            .as_array()
            .ok_or("Malformed lexical helper transport fragments")?;
        let mut writer = BoundedWriter(Vec::new());
        for id in ids {
            let text = super::transport_lexical::string(self.child(id, index, depth)?)?;
            writer
                .write_all(text.as_bytes())
                .map_err(|error| error.to_string())?;
        }
        let text = String::from_utf8(writer.0).map_err(|error| error.to_string())?;
        self.charge(text.len())?;

        Ok(Value::String(text))
    }

fn charge(&mut self, bytes: usize) -> Result<(), String> {
        crate::evidence_budget::charge(
            &mut self.remaining,
            bytes,
            "Helper restoration exceeds explicit 8 MiB work budget",
        )
    }

fn check_depth(depth: usize) -> Result<(), String> {
    if depth > MAX_TREE_DEPTH {
        return Err("Helper transport exceeds explicit tree-depth budget 256".into());
    }

    Ok(())
}

fn render(value: &Value, format: &str) -> Result<String, String> {
    let mut writer = BoundedWriter(Vec::new());
    match format {
        "compact" => serde_json::to_writer(&mut writer, value),
        "pretty" => serde_json::to_writer_pretty(&mut writer, value),
        _ => return Err("Unsupported helper JSON-string format".into()),
    }
    .map_err(|error| error.to_string())?;

    String::from_utf8(writer.0).map_err(|error| error.to_string())
}

pub(super) fn string(value: Value) -> Result<String, String> {
    match value {
        Value::String(text) => Ok(text),
        _ => Err("Lexical helper transport requires string fragments".into()),
    }
}

pub(crate) fn charge(remaining: &mut usize, bytes: usize, reason: &str) -> Result<(), String> {
    *remaining = remaining.checked_sub(bytes).ok_or(reason)?;
    Ok(())
}

pub fn new(stage: &'a str, identity: &'a str, evidence: Option<&'a [u8]>) -> Self {
        Self {
            stage,
            identity,
            evidence,
        }
    }

/// Invoke once, retaining the original result even if diagnostic IO fails.
    pub fn observe<T, E>(self, operation: impl FnOnce() -> Result<T, E>) -> Result<T, E> {
        if enabled() {
            Observation::start(self.stage, self.identity, self.evidence).run(operation)
        } else {
            operation()
        }
    }

fn enabled() -> bool {
    static ENABLED: OnceLock<bool> = OnceLock::new();
    *ENABLED.get_or_init(|| switch("RSTYLE_PERF"))
}

fn start(stage: &'a str, identity: &'a str, evidence: Option<&[u8]>) -> Self {
        let (depth, visit) = COUNTS.with_borrow_mut(|counts| {
            counts.depth += 1;
            let visit = counts
                .visits
                .entry(format!("{stage}:{identity}"))
                .or_default();
            *visit += 1;
            (counts.depth, *visit)
        });
        let event = Event {
            schema: "rstyle.performance-event/2",
            observation_id: ObservationId::next(),
            stage,
            identity,
            pid: std::process::id(),
            event: "start",
            depth,
            visit,
            evidence_bytes: evidence.map_or(0, <[u8]>::len),
            elapsed_seconds: 0.0,
            verification_policy: if crate::verification_policy::is_generated() {
                "trusted-generated"
            } else {
                "strict"
            },
        };
        event.emit();

        Self {
            event,
            started: Instant::now(),
        }
    }

fn run<T, E>(mut self, operation: impl FnOnce() -> Result<T, E>) -> Result<T, E> {
        let result = operation();
        self.finish(result.is_ok());

        result
    }

fn emit(&self) {
        if let Ok(json) = serde_json::to_string(self) {
            let _ = writeln!(std::io::stderr().lock(), "rstyle-perf {json}");
        }
    }

/// Build and validate one bounded normal-flow pair from captured frontend facts.
pub fn produce(facts: &dyn crate::unit_store::EvidenceFacts) -> Result<Pair, Vec<String>> {
    crate::verification_session::within(|| produce_function(facts))
}

fn produce_function(facts: &dyn crate::unit_store::EvidenceFacts) -> Result<Pair, Vec<String>> {
    let observation = crate::diagnostics::Stage::new("producer.produce", &facts.name, None).enter();
    let graph = lower(facts).map_err(|e| {
        e.diagnostics
            .into_iter()
            .map(|d| d.reason)
            .collect::<Vec<_>>()
    })?;
    let analysis = analyze_facts(&graph, facts).map_err(|e| vec![e])?;
    let revision = facts
        .build
        .producer_revision
        .known_value()
        .ok_or_else(|| vec!["Missing captured producer revision".to_string()])?;
    let mut pair = emit(facts, &graph, &analysis, revision).map_err(|e| vec![e])?;
    verify(&pair, facts)?;
    let profile =
        crate::extraction_profile::ExtractionProfile::from_facts(facts).map_err(|e| vec![e])?;
    pair.pdg.extraction_evidence.conformance = crate::Conformance {
        status: crate::ConformanceStatus::Conformant,
        reasons: vec![conformance_reason(profile)],
    };

    observation.finish(Ok(pair))
}

fn analyze_facts(
    graph: &Graph,
    facts: &dyn crate::unit_store::EvidenceFacts,
) -> Result<Analysis, String> {
    if crate::extraction_profile::ExtractionProfile::from_facts(facts)?
        .supports("rust.scalar-loops")
        && graph
            .nodes
            .iter()
            .any(|node| matches!(node.construct.as_deref(), Some("while" | "loop")))
    {
        analyze_cyclic(graph)
    } else {
        analyze(graph)
    }
}

/// Keep historical R0 wording distinct from local expansion conformance.
fn conformance_reason(profile: crate::extraction_profile::ExtractionProfile) -> String {
    if profile == crate::extraction_profile::ExtractionProfile::R0 {
        return "Validated compat.rust.hir-r0/0.1.0 normal-flow extraction within the closed scalar subset exercised by the independent R0 fixtures; exceptional flow/cleanup omitted, no purity or rewrite-safety claim".to_string();
    }
    let policy = profile.policy();

    format!(
        "Validated {}/{} bounded normal-flow extraction; local expansions are not pinned compat R0 conformance; exceptional flow/cleanup omitted, no purity or rewrite-safety claim",
        policy.id, policy.version
    )
}

pub fn lower(facts: &dyn crate::unit_store::EvidenceFacts) -> Result<Graph, HirEligibility> {
    let eligibility = crate::classify(facts);
    if eligibility.status != EligibilityVerdict::Eligible {
        return Err(eligibility);
    }
    if let Some(node) = incomplete_shape(&facts.body) {
        return Err(HirEligibility {
            status: EligibilityVerdict::Unknown,
            diagnostics: vec![HirDiagnostic {
                capability: "rust.scalar-computation".to_string(),
                construct: node.kind.clone(),
                span: node.span,
                snippet: node.snippet.clone(),
                severity: "error".to_string(),
                reason: "Required resolved frontend child correspondence is incomplete; recapture compiler evidence before extraction.".to_string(),
            }],
        });
    }
    let mut builder = Builder {
        loops: Vec::new(),
        facts,
        nodes: Vec::new(),
        transfers: Vec::new(),
        sites: Vec::new(),
    };
    builder.inputs();
    let entry = Flow {
        ends: vec![End {
            node: "E".to_string(),
            kind: "normal".to_string(),
            term: Vec::new(),
        }],
        value: None,
        normal: true,
    };
    let flow = builder.expression(&facts.body, entry);
    if !flow.ends.is_empty() {
        builder.implicit_return(flow);
    }
    let mut transfers = builder.transfers;
    transfers.sort();
    transfers.dedup();

    Ok(Graph {
        nodes: builder.nodes,
        transfers,
        value_sites: builder.sites,
    })
}

pub fn emit(
    facts: &dyn EvidenceFacts,
    graph: &Graph,
    analysis: &Analysis,
    revision: &str,
) -> Result<Pair, String> {
    validate_exception_transfers(graph)?;
    let assessment = super::hazards::assess(facts, graph, analysis)?;
    let producer = emission_producer(facts, graph, revision)?;
    let mut extensions = extensions(facts, graph, analysis)?;
    if crate::extraction_profile::ExtractionProfile::from_facts(facts)?
        .supports("rust.integer-casts")
    {
        extensions.insert(
            super::casts::KEY.into(),
            super::casts::evidence(facts, graph)?,
        );
    }
    extensions.insert(
        format!("{PREFIX}:exceptional-flow-assessment"),
        serde_json::to_value(&assessment).map_err(|e| e.to_string())?,
    );
    if crate::extraction_profile::ExtractionProfile::from_facts(facts)?
        .supports("rust.verified-primitive-summaries")
    {
        extensions.insert(
            crate::call_summaries::KEY.into(),
            super::summaries::evidence(facts, graph)?,
        );
    }
    let metadata = DocumentMetadata {
        producer,
        extensions,
        limitations: assessment.limitations,
    };
    let pdg = pdg_document(facts, graph, analysis, &metadata);
    let cfg = cfg_document(facts, graph, metadata);

    super::profile::apply(Pair { pdg, cfg }, facts, graph)
}

pub fn verify(
    pair: &Pair,
    facts: &dyn crate::unit_store::EvidenceFacts,
) -> Result<(), Vec<String>> {
    verify_view(pair.as_view(), facts)
}

pub(crate) fn within<T>(operation: impl FnOnce() -> T) -> T {
    let root = ACTIVE.with_borrow_mut(|active| {
        if active.is_some() {
            false
        } else {
            *active = Some(Session::default());
            true
        }
    });
    let _root = Root(root);

    operation()
}

pub(crate) fn verify(input: &dyn EvidenceFacts) -> Result<Checked<'_>, String> {
    if !crate::extraction_profile::facts_support(input, VALUE_CAPABILITY) {
        return Err(
            "Digit product values require their registered whole-function capability".into(),
        );
    }
    let instance = instance(input)?;
    let tree = TypeTree::ScalarProductInstance(Box::new(instance.clone()));
    let resolution = input.nominal_resolution()?;
    let digits = resolution.checked_scalar_product_digits(input.facts(), &tree)?;
    let matched = body::verify(input)?;
    let prefix = semantics::verify(matched, input)?;
    if prefix.consumed() != digits {
        return Err("Digit product prefix length differs from its original concrete method".into());
    }
    let variant = variants::verify(&prefix, &instance, input)?;
    let context = constructors::Context {
        resolution: &resolution,
        instance: &instance,
    };
    let constructor = constructors::verify(variant.product, input, &context)?;
    if constructor.fields()[0] != prefix.remainder() {
        return Err("Digit product first field must retain the exact saved suffix value".into());
    }

    Ok(Checked {
        root: &input.body,
        some: variant.some,
        prefix,
        constructor,
        instance,
    })
}

pub(crate) fn instance(&self) -> &Instance {
        &self.instance
    }

pub(crate) fn candidate(facts: &dyn EvidenceFacts) -> bool {
    if !crate::extraction_profile::facts_support(facts, VALUE_CAPABILITY)
        || facts.body.kind != "expr_block"
        || !matches!(facts.body.children.as_slice(), [matched] if matched.kind == "expr_match")
    {
        return false;
    }
    let Some(text) = facts.signature.return_ty.normalized.as_deref() else {
        return false;
    };
    let Ok(TypeToken::Option(payload)) = crate::data_types::parse(text) else {
        return false;
    };

    matches!(*payload, TypeToken::ScalarProductInstance { .. })
}

pub(super) fn verify(input: &dyn EvidenceFacts) -> Result<&HirNode, String> {
    let source: syn::ItemFn =
        syn::parse_str(&input.source.bytes).map_err(|error| error.to_string())?;
    if input.signature.has_self
        || input.signature.receiver.is_some()
        || source.sig.receiver().is_some()
        || input.signature.is_async
        || input.signature.is_unsafe
        || input.signature.is_variadic
        || source.sig.asyncness.is_some()
        || source.sig.unsafety.is_some()
        || source.sig.variadic.is_some()
        || source.sig.abi.is_some()
        || !source.attrs.is_empty()
    {
        return Err(
            "Digit product activation requires an original ordinary receiver-free function".into(),
        );
    }
    let [syn::Stmt::Expr(syn::Expr::Match(original), None)] = source.block.stmts.as_slice() else {
        return Err("Digit product activation requires its complete single-match body".into());
    };
    let root = &input.body;
    let [matched] = root.children.as_slice() else {
        return Err("Digit product body cannot omit or append statements".into());
    };
    if root.kind != "expr_block"
        || root.expansion.is_some()
        || root.dispatch.is_some()
        || root.is_unsafe_block
        || root.span
            != crate::source_evidence::original_span(&input.source.bytes, source.block.span())
        || matched.span
            != crate::source_evidence::original_span(&input.source.bytes, original.span())
        || crate::source_evidence::byte_range(&input.source.bytes, root.span)? != root.snippet
        || crate::source_evidence::byte_range(&input.source.bytes, matched.span)? != matched.snippet
    {
        return Err("Digit product body extent differs from its complete original source".into());
    }

    Ok(matched)
}

pub(super) fn verify<'a>(
    prefix: &semantics::Checked<'a>,
    instance: &Instance,
    input: &dyn EvidenceFacts,
) -> Result<CheckedVariant<'a>, String> {
    let success = success_body(prefix, input)?;
    let [product] = success.children.as_slice() else {
        return Err("Digit product Some must contain exactly one product value".into());
    };
    let payload =
        TypeToken::from_tree(&TypeTree::ScalarProductInstance(Box::new(instance.clone())));
    let option = TypeToken::Option(Box::new(payload.clone()));
    for node in [
        &input.body,
        prefix.matched(),
        prefix.success(),
        success,
        prefix.failure(),
    ] {
        if crate::data_aggregates::parsed_type(node)? != option {
            return Err(
                "Digit product body or variant disagrees with its exact Option instance".into(),
            );
        }
    }
    if crate::data_aggregates::parsed_type(product)? != payload {
        return Err("Digit product Some payload type disagrees with its exact instance".into());
    }

    some(success, product, input)?;
    Ok(CheckedVariant {
        some: success,
        product,
    })
}

pub(crate) fn verify<'a>(
    node: &'a HirNode,
    facts: &dyn EvidenceFacts,
    context: &Context<'_>,
) -> Result<CheckedConstructor<'a>, String> {
    context.instance.check_shape()?;
    let observation = Observation::decode(node)?;
    identity::verify(&observation, facts, context.instance)?;
    selection::verify(&observation, facts, context.instance)?;

    let fields = source::verify(node, facts, context, &observation)?;
    Ok(CheckedConstructor { node, fields })
}

/// Return the concrete digit count only after rechecking the exact owning
    /// function, instance and current SourceContext through its source receipt.
    pub(crate) fn checked_scalar_product_digits(
        &self,
        facts: &HirFnFacts,
        tree: &TypeTree,
    ) -> Result<u8, String> {
        if !self.checked_scalar_product(facts, tree)? {
            return Err("Digit source requires its exact scalar product instance".into());
        }

        self.scalar_product_source
            .as_ref()
            .ok_or("Missing checked scalar product source")?
            .digits()
    }

/// A missing or unrecognized extraction profile never grants a capability.
pub(crate) fn facts_support(facts: &crate::HirFnFacts, capability: &str) -> bool {
    ExtractionProfile::from_facts(facts).is_ok_and(|profile| profile.supports(capability))
}

pub fn policy_supports(policy: &ProfileId, capability: &str) -> bool {
    from_policy(policy).is_some_and(|profile| profile.supports(capability))
}

pub fn from_facts(facts: &HirFnFacts) -> Result<Self, String> {
        match facts.build.frontend_options.get(SELECTION_KEY) {
            None => Ok(Self::R0),
            Some(value) => value
                .as_str()
                .ok_or_else(|| "Malformed extraction profile evidence".to_string())
                .and_then(Self::parse),
        }
    }

/// Call only after selecting this registered whole-function frontier. This
/// checks source semantics, not product ownership, arithmetic or serialized CFG.
pub(crate) fn verify<'a>(
    node: &'a HirNode,
    facts: &'a dyn EvidenceFacts,
) -> Result<Checked<'a>, String> {
    if !crate::extraction_profile::facts_support(facts, super::CAPABILITY) {
        return Err("Prefix semantics require their registered source capability".into());
    }
    let (scrutinee, success, failure) = matched::verify(node, facts)?;
    let pattern = &node.children[1].children[0];
    let prefix = super::source::verify(pattern, facts)?;
    let digits = values::digits(&prefix, success, facts)?;
    let remainder = values::remainder(&prefix, success, facts)?;

    Ok(Checked {
        matched: node,
        scrutinee,
        formal: &facts.signature.params[0].pat,
        prefix,
        success,
        failure,
        digits,
        remainder,
    })
}

pub(crate) fn verify(
    pair: PairView<'_>,
    checked: &Checked<'_>,
    facts: &dyn EvidenceFacts,
) -> Result<(), String> {
    let expected = expected(pair, checked)?;
    let actual: Contract = serde_json::from_value(
        pair.pdg
            .extensions
            .get(KEY)
            .ok_or("Missing complete guarded digit-product origin inventory")?
            .clone(),
    )
    .map_err(|error| error.to_string())?;

    if actual != expected {
        return Err(
            "Digit-product origin inventory changes source components or saved graph values".into(),
        );
    }

    inventory::types(pair, &expected, facts)?;
    inventory::annotations(pair, &expected)
}

pub(crate) fn verify<'a>(pair: PairView<'a>, checked: &Checked<'_>) -> Result<Replay<'a>, String> {
    let replay = operations::collect(pair, checked)?;
    operations::saved(pair, checked, replay.saved)?;
    operations::construct_spans(checked, &replay)?;
    let cfg = flow::Flow::new(pair)?;
    cfg.before(replay.saved, replay.length)?;
    selectors(pair, &cfg, &replay)?;
    bindings::verify(pair, checked, &cfg, &replay)?;
    join::verify(pair, checked, &replay)?;

    Ok(replay)
}

/// Enter a stage whose early returns must also emit a failure event.
    pub fn enter(self) -> Guard<'a> {
        Guard(enabled().then(|| Observation::start(self.stage, self.identity, self.evidence)))
    }

fn finish(&mut self, success: bool) {
        self.event.event = if success { "finish" } else { "failure" };
    }

