fn inherited(
    modules: &[census::Module],
    namespace: &[String],
    configuration: &crate::conditional_source::Configuration<'_>,
) -> Result<BTreeMap<String, syn::ItemMacro>, String> {
    let mut definitions = BTreeMap::new();
    for depth in 0..namespace.len() {
        let parent = modules
            .iter()
            .find(|module| module.namespace == namespace[..depth])
            .ok_or("Cleanup macro scope lacks its original ancestor")?;
        for item in &parent.items {
            if !configuration.active(crate::conditional_source::item_attributes(item))? {
                continue;
            }
            if matches!(item, syn::Item::Mod(module) if module.ident == namespace[depth]) {
                break;
            }
            if let syn::Item::Macro(item) = item
                && let Some(name) = &item.ident
            {
                definitions.insert(name.to_string(), item.clone());
            }
            if let syn::Item::Mod(module) = item
                && imports_macros(module, configuration)?
            {
                definitions.extend(imported_definitions(
                    modules,
                    parent,
                    module,
                    configuration,
                )?);
            }
        }
    }
    Ok(definitions)
}

fn imports_macros(
    module: &syn::ItemMod,
    configuration: &crate::conditional_source::Configuration<'_>,
) -> Result<bool, String> {
    let mut imported = false;
    for attribute in configuration.effective_attributes(&module.attrs)? {
        if attribute.path().is_ident("macro_use") {
            if !matches!(attribute, syn::Meta::Path(_)) {
                return Err(
                    "Cleanup module macro import requires exact whole-module grammar".into(),
                );
            }
            imported = true;
        }
    }
    Ok(imported)
}

fn imported_definitions(
    modules: &[census::Module],
    parent: &census::Module,
    module: &syn::ItemMod,
    configuration: &crate::conditional_source::Configuration<'_>,
) -> Result<BTreeMap<String, syn::ItemMacro>, String> {
    let namespace: Vec<_> = parent
        .namespace
        .iter()
        .cloned()
        .chain([module.ident.to_string()])
        .collect();
    let child = modules
        .iter()
        .find(|child| child.namespace == namespace)
        .ok_or("Missing verified macro import source")?;
    let mut definitions = BTreeMap::new();

    for item in &child.items {
        if !configuration.active(crate::conditional_source::item_attributes(item))? {
            continue;
        }
        let syn::Item::Macro(item) = item else {
            return Err("Cleanup macro import contains nondefinitions".into());
        };
        if !item.mac.path.is_ident("macro_rules") {
            return Err("Cleanup macro import is not an original macro_rules definition".into());
        }
        let name = item
            .ident
            .as_ref()
            .ok_or("Cleanup macro import lacks definition")?;
        definitions.insert(name.to_string(), item.clone());
    }
    Ok(definitions)
}

fn scope<'a>(
        &self,
        items: impl IntoIterator<Item = &'a syn::Item>,
    ) -> Result<BTreeMap<String, bool>, String> {
        let mut scope = BTreeMap::new();
        for item in items {
            if !self
                .configuration
                .active(crate::conditional_source::item_attributes(item))?
            {
                continue;
            }
            self.scope_item(item, &mut scope);
        }
        Ok(scope)
    }

fn scope_item(&self, item: &syn::Item, scope: &mut BTreeMap<String, bool>) {
        let binding = match item {
            syn::Item::Struct(item) => Some((&item.ident, true)),
            syn::Item::Enum(item) => Some((&item.ident, true)),
            syn::Item::Union(item) => Some((&item.ident, true)),
            syn::Item::Trait(item) => {
                scope.insert(format!("trait:{}", item.ident), true);
                Some((&item.ident, false))
            }
            syn::Item::Type(item) => Some((&item.ident, false)),
            syn::Item::Mod(item) => Some((&item.ident, false)),
            syn::Item::Use(item) => {
                self.scope_import(item, scope);
                None
            }
            _ => None,
        };

        if let Some((name, nominal)) = binding {
            source_imports::bind(scope, name.to_string(), nominal);
        }
    }

fn scope_import(&self, item: &syn::ItemUse, scope: &mut BTreeMap<String, bool>) {
        if self.anonymous_import(item) {
            return;
        }
        if let Some(receipt) = self.generated_import(item) {
            for name in receipt.names() {
                source_imports::bind(scope, name.to_string(), false);
            }
            return;
        }

        self.ordinary_import_bindings(item, scope);
    }

pub(super) fn verify(
    facts: &HirFnFacts,
    origins: &Origins,
    resolution: &Resolution,
    owner: Option<&crate::product_instances::CheckedProjection>,
) -> Result<Selection, String> {
    if let Some(selection) = no_drop::payload_errors::selection(facts, resolution)? {
        return Ok(selection);
    }
    verify_ordinary_selection(facts, origins, resolution, owner)
}

fn verify_ordinary_selection(
    facts: &HirFnFacts,
    origins: &Origins,
    resolution: &Resolution,
    owner: Option<&crate::product_instances::CheckedProjection>,
) -> Result<Selection, String> {
    let trees = &resolution.trees;
    let environment = &resolution.environment;
    if trees.is_empty() && !supports(facts, "rust.accelerator-packing")? {
        return Err("Mixed-unit boundary requires selected Copy declarations".into());
    }
    if let Some(owner) = owner {
        if owner.facts() != facts
            || !supports(facts, crate::product_instances::activation::CAPABILITY)?
        {
            return Err("Product source receipt requires its exact owning active instance".into());
        }
        no_drop::copy_products::verify_owner(owner.copy_source(), facts, environment)?;
    }
    let checker = DeclarationChecker {
        owner,
        facts,
        origins,
        environment,
        resolution,
    };
    let mut selection = Selection::default();
    // A closed source unit already proves its historical nominal grammar.
    // Activate only new static products there; mixed units still require every
    // selected declaration to pass the existing complete ownership boundary.
    let static_only = !environment.copy_boundary && resolution.range_value.is_none();
    for (key, tree) in trees {
        if resolution.checked_scalar_product(facts, tree)? {
            continue;
        }
        if static_only && !no_drop::copy_components::required(tree) {
            continue;
        }
        selection.record(key, checker.verify(key, tree)?);
    }

    for (key, tree) in trees {
        if resolution.checked_scalar_product(facts, tree)? {
            continue;
        }
        if static_only && !no_drop::copy_components::required(tree) {
            continue;
        }
        if !selection.copies.contains(key) && !selection.no_drop.contains(key) {
            borrowed::verify(facts, tree, &selection.copies)?;
        }
    }
    Ok(selection)
}

fn record(&mut self, key: &Namespace, checked: CheckedDeclaration) {
        if checked.copy {
            self.copies.insert(key.clone());
        }
        if checked.no_drop {
            self.no_drop.insert(key.clone());
        }
        self.requirements = self.requirements.including(&checked);
    }

/// Select a complete error family and, when separately activated, its exact
/// success product. Every collected dependency receives its own proof.
pub(in crate::nominal_boundary::resolution) fn selection(
    facts: &HirFnFacts,
    resolution: &Resolution,
) -> Result<Option<super::super::Selection>, String> {
    if !supports(facts, crate::named_error_payloads::CAPABILITY)? {
        return Ok(None);
    }
    let interface = facts
        .build
        .frontend_options
        .data::<InterfaceObservations>()?;
    let Observation::Captured { ty } = &interface.result else {
        return Ok(None);
    };
    let product = reader_product(facts, ty)?;
    let id_product = id_reader_product(facts, ty)?;
    let error = match ty {
        TypeTree::Result { ok, err }
            if product.is_some() || id_product.is_some() || scalar_success(facts, ok)? =>
        {
            err.as_ref()
        }
        TypeTree::Struct { fields, .. } if matches!(fields.as_slice(), [field] if matches!(field.ty, TypeTree::MixedEnum { .. })) => {
            ty
        }
        _ => return Ok(None),
    };
    if !matches!(error, TypeTree::Struct { fields, .. } if matches!(fields.as_slice(), [field] if field.name == "0" && matches!(field.ty, TypeTree::MixedEnum { .. })))
    {
        return Ok(None);
    }
    if !supported(error) {
        return Err("Named error requires its complete cleanup grammar".into());
    }
    verify(facts, resolution, error)?;

    Ok(Some(select_dependencies(
        facts, resolution, product, id_product,
    )?))
}

pub fn active(&self, attributes: &[syn::Attribute]) -> Result<bool, String> {
        let mut unknown = None;
        for attribute in attributes {
            match self.attribute(&attribute.meta) {
                Ok(false) => return Ok(false),
                Err(error) => unknown = Some(error),
                Ok(true) => {}
            }
        }
        unknown.map_or(Ok(true), Err)
    }

/// Return active attribute metadata without hiding non-cfg attributes.
    /// Item presence must still be checked with `active`; this is not a proof
    /// that an attribute's expansion or effects are supported.
    pub fn effective_attributes(&self, attributes: &[syn::Attribute]) -> Result<Vec<Meta>, String> {
        let mut effective = Vec::new();
        for attribute in attributes {
            self.expand_attribute(&attribute.meta, &mut effective)?;
        }

        Ok(effective)
    }

fn attribute(&self, meta: &Meta) -> Result<bool, String> {
        if meta.path().is_ident("cfg") {
            let Meta::List(list) = meta else {
                return Err("Malformed cfg attribute".into());
            };
            return self.predicate(
                &list
                    .parse_args::<Meta>()
                    .map_err(|error| error.to_string())?,
            );
        }
        if meta.path().is_ident("cfg_attr") {
            let Meta::List(list) = meta else {
                return Err("Malformed cfg_attr attribute".into());
            };
            let arguments = list
                .parse_args_with(Punctuated::<Meta, Token![,]>::parse_terminated)
                .map_err(|error| error.to_string())?;
            let mut arguments = arguments.iter();
            let condition = arguments.next().ok_or("Missing cfg_attr condition")?;
            if !self.predicate(condition)? {
                return Ok(true);
            }
            for attribute in arguments {
                if !self.attribute(attribute)? {
                    return Ok(false);
                }
            }
        }
        Ok(true)
    }

pub fn new(stage: &'a str, identity: &'a str, evidence: Option<&'a [u8]>) -> Self {
        Self {
            stage,
            identity,
            evidence,
        }
    }

/// Invoke once, retaining the original result even if diagnostic IO fails.
    pub fn observe<T, E>(self, operation: impl FnOnce() -> Result<T, E>) -> Result<T, E> {
        if enabled() {
            Observation::start(self.stage, self.identity, self.evidence).run(operation)
        } else {
            operation()
        }
    }

fn start(stage: &'a str, identity: &'a str, evidence: Option<&[u8]>) -> Self {
        let (depth, visit) = COUNTS.with_borrow_mut(|counts| {
            counts.depth += 1;
            let visit = counts
                .visits
                .entry(format!("{stage}:{identity}"))
                .or_default();
            *visit += 1;
            (counts.depth, *visit)
        });
        let event = Event {
            schema: "rstyle.performance-event/2",
            observation_id: ObservationId::next(),
            stage,
            identity,
            pid: std::process::id(),
            event: "start",
            depth,
            visit,
            evidence_bytes: evidence.map_or(0, <[u8]>::len),
            elapsed_seconds: 0.0,
            verification_policy: if crate::verification_policy::is_generated() {
                "trusted-generated"
            } else {
                "strict"
            },
        };
        event.emit();

        Self {
            event,
            started: Instant::now(),
        }
    }

fn run<T, E>(mut self, operation: impl FnOnce() -> Result<T, E>) -> Result<T, E> {
        let result = operation();
        self.finish(result.is_ok());

        result
    }

fn finish(&mut self, success: bool) {
        self.event.event = if success { "finish" } else { "failure" };
    }

fn emit(&self) {
        if let Ok(json) = serde_json::to_string(self) {
            let _ = writeln!(std::io::stderr().lock(), "rstyle-perf {json}");
        }
    }

fn enabled() -> bool {
    static ENABLED: OnceLock<bool> = OnceLock::new();
    *ENABLED.get_or_init(|| switch("RSTYLE_PERF"))
}

/// Trust the producer's source correspondence and certified helper summaries.
/// Structural graph validation still runs. Use only around owned current-run
/// production, or explicitly selected diagnostic replay of one's own facts.
/// The policy is thread-local, nested, and restored on early return or unwind.
pub fn generated<T>(operation: impl FnOnce() -> T) -> T {
    with_policy(true, operation)
}

/// Enforce independent imported verification even inside a generated scope.
pub fn strict<T>(operation: impl FnOnce() -> T) -> T {
    with_policy(false, operation)
}

fn with_policy<T>(generated: bool, operation: impl FnOnce() -> T) -> T {
    let previous = GENERATED.with(|active| active.replace(generated));
    let _restore = Restore(previous);

    operation()
}

fn decode(bytes: &[u8]) -> Result<Decoded, String> {
        let mut wire: Self = serde_json::from_slice(bytes).map_err(|error| error.to_string())?;
        if ![
            BUNDLE_SCHEMA,
            "rstyle.shared-unit/6",
            "rstyle.shared-unit/5",
            LEGACY_SCHEMA,
        ]
        .contains(&wire.schema.as_str())
        {
            return Err("Unsupported shared unit schema".into());
        }

        let mut inventories = crate::frontend::option_bundle::ImportedInventories::new(
            wire.inherent_units.take(),
            wire.schema == LEGACY_SCHEMA,
        )?;
        inventories.share_censuses(wire.schema == BUNDLE_SCHEMA);
        let mut sources = crate::source_table::Imported::new(&wire.sources);
        let flat_bodies = [BUNDLE_SCHEMA, "rstyle.shared-unit/6"].contains(&wire.schema.as_str());
        let functions = std::mem::take(&mut wire.functions)
            .into_iter()
            .map(|function| function.into_facts(&mut sources, &mut inventories, flat_bodies))
            .collect::<Result<_, _>>()?;
        sources.finish()?;
        inventories.finish()?;

        Ok(Decoded { wire, functions })
    }

fn into_store(self) -> Result<UnitStore, String> {
        let store = Builder::in_namespace(self.functions, self.wire.namespace)?.store;

        if self.wire.certified.len() != store.functions.len() {
            return Err("Shared unit certification table disagrees".into());
        }
        if self.wire.links.len() != store.links.len() {
            return Err("Incomplete unit call link inventory".into());
        }
        for (wire, expected) in self.wire.links.into_iter().zip(&store.links) {
            validate_links(wire, expected)?;
        }
        u32::try_from(self.wire.helpers.len()).map_err(|_| "Oversized helper table")?;
        u32::try_from(self.wire.graphs.len()).map_err(|_| "Oversized graph table")?;
        let function_count = store.functions.len();
        let mut store = UnitStore {
            namespace: store.namespace,
            functions: store.functions,
            links: store.links,
            graphs: self.wire.graphs,
            roots: self.wire.roots,
            helpers: self.wire.helpers,
            certified: self.wire.certified,
            dependencies: Vec::new(),
            namespace_associations: Vec::new(),
            external_links: vec![BTreeMap::new(); function_count],
            instance: None,
            slice_instance: None,
            reference_instance: None,
            reference_forwarder: None,
            product_instance: None,
        };
        store.validate_roots()?;
        store.validate_certifications()?;
        store.validate_depths()?;
        graph_sources::share(&mut store);
        Ok(store)
    }

fn validate_evidence(&self) -> Result<(), String> {
        let analysis = self.analysis();

        for index in 0..self.helpers.len() {
            let helper = HelperView {
                foreign: false,
                resolver: &analysis,
                id: local_id(index, HelperId)?,
            };
            crate::helper_calls::verify_shared_callee(&helper, &helper.frontend())
                .map_err(|error| format!("Imported helper {}: {error}", helper.frontend().name))?;
            helper.remember();
        }
        self.validate_root_evidence(&analysis)?;
        for (index, certified) in self.certified.iter().enumerate() {
            if certified.is_none()
                && let Some(view) = analysis.function(index)
                && crate::extraction_profile::ExtractionProfile::from_facts(&view)?
                    .supports("rust.verified-helper-calls")
                && crate::classify(&view).status == crate::EligibilityVerdict::Eligible
                && self.requires_new_helper(index, &view)
                && crate::helper_calls::certify_view(&view)
                    .map_err(|error| format!("Imported function {}: {error}", view.name))?
                    .is_some()
            {
                return Err("Incomplete unit helper certification inventory".into());
            }
        }
        Ok(())
    }

fn validate_root_evidence(&self, analysis: &UnitAnalysis<'_>) -> Result<(), String> {
        for (index, root) in self.roots.iter().enumerate() {
            let view = analysis.function(index).ok_or("Missing graph frontend")?;
            let eligible = crate::classify(&view).status == crate::EligibilityVerdict::Eligible;
            if root.is_some() != eligible {
                return Err("Incomplete or contradictory root graph inventory".into());
            }
            if self.certified[index].is_none()
                && let Some(pair) = self.pair(index)
            {
                crate::producer::verify(pair, &view).map_err(|errors| errors.join("; "))?;
            }
        }
        Ok(())
    }

