    /// separate one-body analysis owner. This is not a caller/artifact join.
    /// Ordinary bundle export deliberately rejects this store until original
    /// owner and projection replay have their own checked transport contract.
    pub fn capture_scalar_instance(
        owner: Arc<Self>,
        definition: usize,
        projection: &Projection,
    ) -> Result<Self, String> {
        capture_instance(owner, definition, projection)
    }

fn install_dependency(
    store: &mut UnitStore,
    origin: &OriginalInstance<SpanArgument>,
    checked: &CheckedProjection,
    observation: &Value,
) -> Result<(), String> {
    let Some(local) = checked.local_from() else {
        return if checked.argument() == SpanArgument::Span {
            Ok(())
        } else {
            Err("Product Range projection lacks its checked local From".into())
        };
    };

    let (owner, _, argument) = origin.get();
    let (ordinal, selected) = selected_local(owner, observation)?;
    if argument != SpanArgument::RangeUsize || selected != local {
        return Err("Product dependency differs from its checked original local From".into());
    }

    store.external_links[0].insert(
        site(checked.operation()),
        ExternalTarget {
            dependency: 0,
            function: local_id(ordinal, FunctionId)?,
        },
    );
    store.dependencies.push(Arc::clone(owner));
    Ok(())
}

fn selected_local<'a>(
    owner: &'a UnitStore,
    observation: &Value,
) -> Result<(usize, &'a HirFnFacts), String> {
    let identity = observation["selected_local_from"]["definition"]["definition_identity"]
        .as_str()
        .filter(|value| !value.is_empty())
        .ok_or("Product Range instance lacks its selected local From identity")?;
    let mut candidates = owner.functions.iter().enumerate().filter(|(_, facts)| {
        facts
            .build
            .frontend_options
            .get("definition_identity")
            .and_then(Value::as_str)
            == Some(identity)
    });

    let selected = candidates
        .next()
        .ok_or("Selected local From is absent from the original owner")?;
    if candidates.next().is_some() {
        return Err("Selected local From is ambiguous in the original owner".into());
    }

    if owner.pair(selected.0).is_none()
        || owner.certified.get(selected.0).is_none_or(Option::is_none)
    {
        return Err("Selected local From lacks original complete certification".into());
    }

    Ok(selected)
}

pub(super) fn get(&self) -> (&Arc<UnitStore>, usize, A) {
        (&self.owner, self.definition.0 as usize, self.argument)
    }

pub fn local_from(&self) -> Option<&HirFnFacts> {
        self.local_from.as_deref()
    }

pub fn argument(&self) -> SpanArgument {
        self.argument
    }

pub fn operation(&self) -> &HirNode {
        &self.operation
    }

fn local_id<T>(index: usize, constructor: impl FnOnce(u32) -> T) -> Result<T, String> {
    let id = u32::try_from(index).map_err(|_| "Oversized unit evidence table")?;
    Ok(constructor(id))
}

fn site(node: &HirNode) -> Site {
    (node.hir.krate, node.hir.owner, node.hir.local)
}

/// Resolve a root paired document without recreating or decoding it.
    pub fn pair(&self, index: usize) -> Option<&Pair> {
        let id = self.roots.get(index).copied().flatten()?;
        self.graphs.get(id.0 as usize)
    }

pub fn get(&self, key: &str) -> Option<&Value> {
        self.0.get(key).map(Entry::json)
    }

fn flush(&mut self) -> io::Result<()> {
        self.writer.flush()
    }

fn encode(value: u64) -> String {
    format!("xxh3-64:{value:016x}")
}

fn into_json(self) -> Value {
        match self {
            Self::Json(value) | Self::Invalid { value, .. } => value,
            Self::Interface(record) => record.into_json(),
            Self::Fields(record) => record.into_json(),
            Self::Receivers(record) => record.into_json(),
            Self::Census(record) => record.into_json(),
            Self::GeneratedSources(record) => record.into_json(),
            Self::DependencyNamespaces(record) => record.into_json(),
            Self::Origins(record) => record.into_json(),
            Self::InherentUnits(record) => record.record.into_json(),
        }
    }

fn into_json(mut self) -> Value {
        self.json.take().unwrap_or_else(|| self.render())
    }

fn render(&self) -> Value {
        let mut json = serde_json::to_value(&self.value).expect("typed evidence serializes");
        for path in &self.nulls {
            json.pointer_mut(path)
                .expect("nominal evidence parent")
                .as_object_mut()
                .expect("nominal evidence object")
                .insert("source_identity".into(), Value::Null);
        }
        json
    }
